import 'package:flutter/material.dart';
import 'dart:math';
void main()=>runApp(const MyApp());
class MyApp extends StatelessWidget{const MyApp({super.key});@override Widget build(BuildContext context){return MaterialApp(debugShowCheckedModeBanner:false,title:'Ehliyet 2026',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:Colors.blue)),home:const Home());}}
class Home extends StatelessWidget{const Home({super.key});@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Ehliyet 2026 - Offline'),centerTitle:true),body:ListView(padding:const EdgeInsets.all(16),children:[_c(context,'🚗 Sınav Başlat','50 Soru - Gerçek sınav','_c2',Colors.blue,const Exam()),_c(context,'📚 Konular','Trafik Motor İlkyardım', 'book', Colors.green,const Exam()),_c(context,'⭐ Hızlı Test','10 Soruluk test', 'quiz', Colors.orange,const Exam())]));} Widget _c(BuildContext ctx,String t,String s,String i,Color c,Widget p){return Card(margin:const EdgeInsets.only(bottom:12),child:ListTile(leading:Icon(Icons.play_circle,color:c,size:40),title:Text(t,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(s),trailing:const Icon(Icons.arrow_forward_ios),onTap:()=>Navigator.push(ctx,MaterialPageRoute(builder:(_)=>p))));}}
class Q{final String q;final List<String> o;final int a;Q(this.q,this.o,this.a);}
final List<Q> qs=[Q('Kırmızı ışıkta ne yapılır?',['Durulur','Geçilir','Yavaşlanır','Korna'],0),Q('Emniyet kemeri?',['Süs','Güvenlik','Hız','Yakıt'],1),Q('İlkyardım ilk adım?',['Su ver','112 ara','Yemek','Uyu'],1),Q('Motor yağı kontrol?',['Sıcakken','Soğukken','Yolda','Hiç'],1),Q('Dur levhası?',['Geç','Dur kontrol','Hızlan','Geri'],1),Q('Kalp masajı dk?',['100','10','5','200'],0),Q('Alkol limit?',['0.50 promil','1.00','2.00','Serbest'],0),Q('Fren mesafesi?',['Yol durumu','Renk','Müzik','Koku'],0),Q('Şok pozisyonu?',['Ayak yukarı','Baş yukarı','Otur','Yüzüstü'],0),Q('Akü ne?',['Elektrik','Su','Benzin','Hava'],0),];
class Exam extends StatefulWidget{const Exam({super.key});@override State<Exam> createState()=>_ExamState();}
class _ExamState extends State<Exam>{late List<Q> q;int cur=0;List<int?> ans=[];@override void initState(){super.initState();q=[...qs]..shuffle(Random());q=q.take(10).toList();ans=List.filled(q.length,null);} @override Widget build(BuildContext context){final qu=q[cur];return Scaffold(appBar:AppBar(title:Text('${cur+1}/${q.length}')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.blue.shade50,borderRadius:BorderRadius.circular(8)),child:Text(qu.q,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))),const SizedBox(height:20),...List.generate(qu.o.length,(i)=>Card(color:ans[cur]==i?Colors.blue.shade100:null,child:RadioListTile(value:i,groupValue:ans[cur],title:Text(qu.o[i]),onChanged:(v)=>setState(()=>ans[cur]=v)))),const Spacer(),Row(children:[if(cur>0)Expanded(child:ElevatedButton(onPressed:()=>setState(()=>cur--),child:const Text('Geri'))),const SizedBox(width:10),Expanded(child:ElevatedButton(onPressed:(){if(cur<q.length-1){setState(()=>cur++);}else{int cor=0;for(int i=0;i<q.length;i++){if(ans[i]==q[i].a)cor++;} showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Bitti!'),content:Text('$cor / ${q.length} Doğru'),actions:[TextButton(onPressed:(){Navigator.pop(context);Navigator.pop(context);},child:const Text('Tamam'))]));}},child:Text(cur==q.length-1?'Bitir':'İleri')))])])));}}
